final Map<String, List<String>> analysisDashboardTranslations = {
  'en': analysisDashboardEnglish,
  for (final e in analysisDashboardIndianRows.entries)
    e.key: e.value.split('|'),
  for (final e in analysisDashboardWesternRows.entries)
    e.key: e.value.split('|'),
  for (final e in analysisDashboardGroupB.entries) e.key: e.value.split('|'),
};

String analysisDashboardText(String key, String code,
    [Map<String, String> values = const {}]) {
  final index = analysisDashboardKeys.indexOf(key);
  if (index < 0) throw ArgumentError.value(key, 'key');
  final row =
      analysisDashboardTranslations[AppLanguageController.resolveCode(code)];
  if (row == null) throw StateError('Missing Analysis dashboard locale: $code');
  var result = row[index];
  for (final e in values.entries) {
    result = result.replaceAll('{${e.key}}', e.value);
  }
  return result;
}

